"""
Task 010 — Simple filter expression evaluator

Implements evaluate(expr, record) -> bool
"""

import re


# ---------------------------------------------------------------------------
# Tokeniser
# ---------------------------------------------------------------------------

_TOKEN_SPEC = [
    ('NUMBER',   r'-?\d+(?:\.\d+)?'),          # integer or float, optional neg
    ('STRING',   r"'[^']*'"),                   # single-quoted string
    ('OP',       r'>=|<=|!=|==|>|<'),           # comparison operators
    ('LPAREN',   r'\('),
    ('RPAREN',   r'\)'),
    ('IDENT',    r'[A-Za-z_][A-Za-z0-9_]*'),   # identifier (field name or keyword)
    ('SKIP',     r'[ \t\n\r]+'),                # whitespace to ignore
    ('MISMATCH', r'.'),                          # any other character → error
]

_TOKEN_RE = re.compile(
    '|'.join(f'(?P<{name}>{pattern})' for name, pattern in _TOKEN_SPEC)
)


def _tokenise(expr: str):
    """Return list of (type, value) tokens, skipping whitespace."""
    tokens = []
    for m in _TOKEN_RE.finditer(expr):
        kind = m.lastgroup
        value = m.group()
        if kind == 'SKIP':
            continue
        if kind == 'MISMATCH':
            raise ValueError(f"Unexpected character {value!r} in expression")
        # Classify keywords
        if kind == 'IDENT' and value in ('AND', 'OR', 'NOT'):
            kind = value  # reuse the keyword itself as the token type
        tokens.append((kind, value))
    return tokens


# ---------------------------------------------------------------------------
# Recursive-descent parser + evaluator
# ---------------------------------------------------------------------------

class _Parser:
    def __init__(self, tokens, record):
        self._tokens = tokens
        self._pos = 0
        self._record = record

    # ------------------------------------------------------------------
    # Low-level helpers
    # ------------------------------------------------------------------

    def _peek(self):
        if self._pos < len(self._tokens):
            return self._tokens[self._pos]
        return None

    def _consume(self):
        tok = self._tokens[self._pos]
        self._pos += 1
        return tok

    def _expect(self, kind):
        tok = self._peek()
        if tok is None or tok[0] != kind:
            raise ValueError(
                f"Expected {kind!r} but got {tok!r} at position {self._pos}"
            )
        return self._consume()

    def _at_end(self):
        return self._pos >= len(self._tokens)

    # ------------------------------------------------------------------
    # Grammar rules
    # ------------------------------------------------------------------

    def parse(self):
        result = self._or_expr()
        if not self._at_end():
            raise ValueError(
                f"Unexpected token {self._peek()!r} at position {self._pos}"
            )
        return result

    def _or_expr(self):
        left = self._and_expr()
        while self._peek() and self._peek()[0] == 'OR':
            self._consume()  # consume 'OR'
            right = self._and_expr()
            left = left or right
        return left

    def _and_expr(self):
        left = self._not_expr()
        while self._peek() and self._peek()[0] == 'AND':
            self._consume()  # consume 'AND'
            right = self._not_expr()
            left = left and right
        return left

    def _not_expr(self):
        if self._peek() and self._peek()[0] == 'NOT':
            self._consume()  # consume 'NOT'
            return not self._not_expr()
        return self._comparison()

    def _comparison(self):
        tok = self._peek()
        if tok is None:
            raise ValueError("Unexpected end of expression")

        # Parenthesised sub-expression
        if tok[0] == 'LPAREN':
            self._consume()  # consume '('
            result = self._or_expr()
            self._expect('RPAREN')
            return result

        # Must be:  field op value
        # field is an IDENT (not a keyword)
        if tok[0] != 'IDENT':
            raise ValueError(
                f"Expected field name or '(' but got {tok!r} at position {self._pos}"
            )
        field_tok = self._consume()
        field_name = field_tok[1]

        # operator
        op_tok = self._peek()
        if op_tok is None or op_tok[0] != 'OP':
            raise ValueError(
                f"Expected comparison operator but got {op_tok!r} at position {self._pos}"
            )
        op = self._consume()[1]

        # value (number or string)
        val_tok = self._peek()
        if val_tok is None or val_tok[0] not in ('NUMBER', 'STRING'):
            raise ValueError(
                f"Expected value (number or string) but got {val_tok!r} at position {self._pos}"
            )
        val_tok = self._consume()

        if val_tok[0] == 'NUMBER':
            raw = val_tok[1]
            rhs = float(raw) if '.' in raw else int(raw)
        else:  # STRING
            rhs = val_tok[1][1:-1]  # strip surrounding single quotes

        # Retrieve field from record
        if field_name not in self._record:
            raise KeyError(field_name)

        lhs = self._record[field_name]

        # Type checking
        lhs_numeric = isinstance(lhs, (int, float)) and not isinstance(lhs, bool)
        rhs_numeric = isinstance(rhs, (int, float)) and not isinstance(rhs, bool)
        lhs_str = isinstance(lhs, str)
        rhs_str = isinstance(rhs, str)

        if lhs_numeric and rhs_numeric:
            pass  # ok
        elif lhs_str and rhs_str:
            pass  # ok
        else:
            raise TypeError(
                f"Cannot compare {type(lhs).__name__} with {type(rhs).__name__}"
            )

        if op == '==':
            return lhs == rhs
        elif op == '!=':
            return lhs != rhs
        elif op == '>':
            return lhs > rhs
        elif op == '<':
            return lhs < rhs
        elif op == '>=':
            return lhs >= rhs
        elif op == '<=':
            return lhs <= rhs
        else:
            raise ValueError(f"Unknown operator {op!r}")


# ---------------------------------------------------------------------------
# Public API
# ---------------------------------------------------------------------------

def evaluate(expr: str, record: dict) -> bool:
    """
    Parse and evaluate a simple filter expression against a single record.

    Returns True if the record matches the expression.

    Raises:
        ValueError  — syntax errors
        KeyError    — field referenced in expr is missing from record
        TypeError   — comparison between incompatible types
    """
    tokens = _tokenise(expr)
    if not tokens:
        raise ValueError("Empty expression")
    parser = _Parser(tokens, record)
    return bool(parser.parse())
